using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace TvtLobby.MissionEditor
{
    public sealed class FactionCardsPage : UserControl
    {
        public sealed class FactionCard : UserControl
        {
            public readonly CheckBox DefaultName=new EditorToggle{AutoSize=true,Text="Use faction default name"};public readonly TextBox DisplayName=new TextBox();public readonly ComboBox Alliance=new EditorCombo{DropDownStyle=ComboBoxStyle.DropDown};public readonly Button Apply=new EditorButton{Text="Apply faction",Primary=true};
            public EditorFaction Data;public bool Dirty,Conflict;public string Baseline="";bool loading;string custom="";readonly Label title,meta,note;readonly TableLayoutPanel body;
            public event Action Changed;
            public FactionCard(EditorFaction data,Action remove,Action layers){BackColor=EditorTheme.Panel;AutoSize=true;AutoSizeMode=AutoSizeMode.GrowAndShrink;body=EditorTheme.Stack(20);body.BackColor=BackColor;Controls.Add(body);meta=EditorTheme.Label("",8,EditorTheme.Muted);title=EditorTheme.Label("",15,null,true);EditorTheme.Add(body,meta);EditorTheme.Add(body,title);EditorTheme.Add(body,DefaultName);DisplayName.MaxLength=128;EditorTheme.Add(body,EditorTheme.Field("Mission display name",DisplayName));EditorTheme.Add(body,EditorTheme.Field("Alliance",Alliance,"Same alliance = friendly sides. Empty = no alliance."));note=EditorTheme.Label("",8,EditorTheme.Muted);EditorTheme.Add(body,note);var buttons=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Top};buttons.Controls.Add(Apply);buttons.Controls.Add(EditorTheme.Button("Reload fields",()=>{Dirty=Conflict=false;LoadFields(Data);Signal();}));buttons.Controls.Add(EditorTheme.Button("Remove faction",remove));buttons.Controls.Add(EditorTheme.Button("Restore missing layers",layers));EditorTheme.Add(body,buttons);
                DefaultName.CheckedChanged+=(s,e)=>{if(loading)return;loading=true;if(DefaultName.Checked){custom=DisplayName.Text;DisplayName.Text=Data.DefaultName;}else DisplayName.Text=custom;DisplayName.Enabled=!DefaultName.Checked;loading=false;Edit();};DisplayName.TextChanged+=(s,e)=>Edit();Alliance.TextChanged+=(s,e)=>Edit();LoadFields(data);EditorTheme.Apply(this);}
            public static string Values(EditorFaction d){return (d.Name??"")+"\n"+(d.Alliance??"");}
            public void Accept(EditorFaction data,List<string> alliances){if(Dirty&&Baseline!=Values(data))Conflict=true;Data=data;string prior=Alliance.Text;loading=true;Alliance.Items.Clear();Alliance.Items.Add("");foreach(string a in alliances)Alliance.Items.Add(a);Alliance.Text=prior;loading=false;if(!Dirty)LoadFields(data);else State();}
            void LoadFields(EditorFaction data){Data=data;loading=true;Baseline=Values(data);custom=data.Name??"";DefaultName.Checked=String.IsNullOrEmpty(data.Name);DisplayName.Text=DefaultName.Checked?data.DefaultName:data.Name;DisplayName.Enabled=!DefaultName.Checked;Alliance.Text=data.Alliance??"";loading=false;Dirty=Conflict=false;State();}
            void Edit(){if(loading)return;Dirty=(DefaultName.Checked?"":DisplayName.Text)+"\n"+Alliance.Text.Trim()!=Baseline;State();Signal();}
            void Signal(){if(Changed!=null)Changed();}
            void State(){title.Text=Data.DisplayName;meta.Text=Data.Key+"   ·   "+Data.Slots+" slots   ·   "+Data.Groups+" groups";note.Text=Conflict?"Changed in Workbench. Reload fields before applying.":Dirty?"Modified · unapplied fields":"Groups_"+Data.Key+" · Vehicles_"+Data.Key+(Data.Layers!=0?" · present":" · missing");note.ForeColor=Dirty||Conflict?EditorTheme.Amber:EditorTheme.Muted;Apply.Enabled=Dirty&&!Conflict;}
            public ForcesEdit Read(){return new ForcesEdit{Key=Data.Key,Name=DefaultName.Checked?"":DisplayName.Text,DefaultName=DefaultName.Checked?1:0,Alliance=Alliance.Text.Trim()};}
            public void Applied(){Dirty=Conflict=false;}
        }
        readonly Func<string,ForcesEdit,Task<FoundationReply>> send;readonly TableLayoutPanel cards=EditorTheme.Stack();readonly Dictionary<string,FactionCard> entries=new Dictionary<string,FactionCard>();readonly Button applyAll;ForcesView data=new ForcesView();string session="";
        public event Action DraftChanged;public bool HasDraft{get{return entries.Values.Any(c=>c.Dirty);}}public IEnumerable<FactionCard> Cards{get{return entries.Values;}}
        public string DraftError{get{return entries.Values.Any(c=>c.Conflict)?"A faction changed in Workbench. Reload its fields first.":entries.Values.Any(c=>c.Dirty&&!c.DefaultName.Checked&&String.IsNullOrWhiteSpace(c.DisplayName.Text))?"Enter a faction display name or use its default name.":null;}}
        public async Task<bool> ApplyPending(){foreach(var c in entries.Values.Where(c=>c.Dirty).ToList()){if(DraftError!=null)return false;var r=await send("faction_update",c.Read());if(r.Ok!=1)return false;}return !HasDraft;}
        public FactionCardsPage(Func<string,ForcesEdit,Task<FoundationReply>> callback){send=callback;Dock=DockStyle.Fill;BackColor=EditorTheme.Background;var frame=EditorTheme.Stack();frame.Dock=DockStyle.Fill;frame.AutoSize=false;frame.AutoScroll=true;var top=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Top};top.Controls.Add(EditorTheme.Button("+ Add faction",()=>AddDialog(),true));top.Controls.Add(EditorTheme.Button("Create faction…",()=>{if(data.NativeFactionCreationVersion<1){MessageBox.Show(this,"Save and restart Workbench, then reopen Mission Editor to load native faction creation.","Workbench scripts need updating");return;}using(var dialog=new NativeFactionDialog(data,send))dialog.ShowDialog(this);}));EditorTheme.Add(frame,top);cards.ColumnCount=2;cards.ColumnStyles.Clear();cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));EditorTheme.Add(frame,cards);applyAll=EditorTheme.Button("Apply factions",async()=>{foreach(var c in entries.Values.Where(x=>x.Dirty&&!x.Conflict).ToList()){var result=await send("faction_update",c.Read());if(result.Ok!=1)break;}},true);EditorTheme.Add(frame,applyAll);EditorTheme.Add(frame,EditorTheme.Label("Adding a faction creates its Groups and Vehicles layers. Place groups and vehicles in World Editor. Removing a faction keeps world objects; existing references must be resolved first.",9,EditorTheme.Muted));Controls.Add(frame);SizeChanged+=(s,e)=>ArrangeCards();}
        void AddDialog(){using(var dialog=new Form{Text="Add faction",ClientSize=new Size(550,230),StartPosition=FormStartPosition.CenterParent,BackColor=EditorTheme.Panel,ForeColor=EditorTheme.Text,Font=EditorTheme.Font(),FormBorderStyle=FormBorderStyle.FixedDialog,MinimizeBox=false,MaximizeBox=false}){var p=EditorTheme.Stack(24);var choice=new EditorCombo{Dock=DockStyle.Top};foreach(var f in data.Available.Where(f=>!data.Factions.Any(x=>x.Key==f.Key)))choice.Items.Add(f);if(choice.Items.Count>0)choice.SelectedIndex=0;EditorTheme.Add(p,EditorTheme.Field("Available factions",choice));EditorTheme.Add(p,EditorTheme.Label("Adds the faction and its Groups / Vehicles layers to this mission.",9,EditorTheme.Muted));var add=EditorTheme.Button("Add to mission",async()=>{var f=choice.SelectedItem as EditorFaction;if(f==null)return;var result=await send("faction_add",new ForcesEdit{Key=f.Key});if(result.Ok==1)dialog.Close();},true);add.Enabled=choice.Items.Count>0;EditorTheme.Add(p,add);dialog.Controls.Add(p);dialog.ShowDialog(this);}}
        public void Accept(FoundationReply reply,bool replace){if(replace||session!=reply.WorldSession){foreach(var c in entries.Values)c.Applied();}session=reply.WorldSession;data=reply.Forces??new ForcesView();foreach(string key in entries.Keys.Where(k=>!data.Factions.Any(f=>f.Key==k)).ToList()){entries[key].Dispose();entries.Remove(key);}foreach(var f in data.Factions){FactionCard card;if(!entries.TryGetValue(f.Key,out card)){string key=f.Key;card=new FactionCard(f,async()=>{if(MessageBox.Show(this,"Remove this faction's mission entry? World objects and layers are retained.","Remove faction",MessageBoxButtons.OKCancel)==DialogResult.OK)await send("faction_remove",new ForcesEdit{Key=key});},async()=>await send("faction_layers",new ForcesEdit{Key=key}));card.Changed+=State;var captured=card;card.Apply.Click+=async(s,e)=>await send("faction_update",captured.Read());entries.Add(f.Key,card);}card.Accept(f,data.Alliances);}ArrangeCards();State();}
        void ArrangeCards(){cards.SuspendLayout();cards.Controls.Clear();cards.RowStyles.Clear();int columns=Width<840?1:2;cards.ColumnCount=columns;cards.ColumnStyles.Clear();for(int i=0;i<columns;i++)cards.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/columns));cards.RowCount=0;int n=0;foreach(var c in entries.Values){int row=n/columns;if(row>=cards.RowCount){cards.RowCount++;cards.RowStyles.Add(new RowStyle(SizeType.AutoSize));}c.Margin=new Padding(0,0,n%columns==0&&columns==2?16:0,18);c.Dock=DockStyle.Fill;cards.Controls.Add(c,n%columns,row);n++;}if(n==0){cards.RowCount=1;var empty=EditorTheme.Label("No factions added\n\nAdd a participating faction to create its Groups and Vehicles layers.",12,EditorTheme.Muted);empty.Padding=new Padding(24);cards.Controls.Add(empty,0,0);}cards.ResumeLayout(true);}
        void State(){applyAll.Enabled=entries.Values.Any(c=>c.Dirty)&&!entries.Values.Any(c=>c.Conflict);if(DraftChanged!=null)DraftChanged();}
        public void Applied(string key){if(entries.ContainsKey(key))entries[key].Applied();}
        public bool CanLeave(){return !HasDraft||MessageBox.Show(this,"Discard unapplied faction fields?","Unapplied fields",MessageBoxButtons.OKCancel)==DialogResult.OK;}
    }
}
